-- DELTABOTS PULSE D1 SQLite baseline migration 0001
-- UTC dates ISO8601 strings; IDs opaque ULID/UUID generated in app. NOT a deployed schema.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT,locale TEXT NOT NULL DEFAULT 'pt-BR',timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleting','deleted')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS user_credentials(user_id TEXT PRIMARY KEY REFERENCES users(id),password_hash TEXT,oidc_subject TEXT,mfa_enabled INTEGER NOT NULL DEFAULT 0 CHECK(mfa_enabled IN(0,1)),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,plan_id TEXT NOT NULL DEFAULT 'personal',status TEXT NOT NULL DEFAULT 'active',created_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS org_members(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('owner','org_admin','developer','member','operator')),status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL, UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),tenant_id TEXT NOT NULL REFERENCES organizations(id),refresh_hash TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL,last_seen_at TEXT,device_label TEXT);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS gateways(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN('android','mqtt_bridge','ws_gateway')),display_name TEXT,public_key TEXT,credential_version INTEGER NOT NULL DEFAULT 1,last_seen_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS gateways_tenant ON gateways(tenant_id,last_seen_at);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),gateway_id TEXT REFERENCES gateways(id),model TEXT NOT NULL,firmware TEXT,manufacturer TEXT,alias TEXT,transport TEXT NOT NULL DEFAULT 'ble',last_seen_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,revoked_at TEXT);
CREATE INDEX IF NOT EXISTS devices_tenant ON devices(tenant_id,owner_user_id,last_seen_at);
CREATE TABLE IF NOT EXISTS device_bindings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),device_id TEXT NOT NULL REFERENCES devices(id),gateway_id TEXT NOT NULL REFERENCES gateways(id),valid_from TEXT NOT NULL,valid_to TEXT,UNIQUE(device_id,gateway_id,valid_from));
CREATE TABLE IF NOT EXISTS device_capabilities(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),device_id TEXT NOT NULL REFERENCES devices(id),capability TEXT NOT NULL,support_state TEXT NOT NULL CHECK(support_state IN('SUPPORTED','UNSUPPORTED','UNVERIFIED','TEMPORARILY_UNAVAILABLE')),firmware TEXT,driver_version TEXT,verified_at TEXT,test_artifact TEXT,details_json TEXT NOT NULL DEFAULT '{}',UNIQUE(device_id,capability,firmware));
CREATE TABLE IF NOT EXISTS consents(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT NOT NULL REFERENCES users(id),purpose TEXT NOT NULL,scope_json TEXT NOT NULL DEFAULT '{}',granted_at TEXT NOT NULL,revoked_at TEXT,expires_at TEXT,policy_version TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS consents_user ON consents(tenant_id,user_id,purpose,revoked_at);
CREATE TABLE IF NOT EXISTS share_invitations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),invitee_email_hash TEXT NOT NULL,grant_json TEXT NOT NULL,token_hash TEXT NOT NULL,expires_at TEXT NOT NULL,accepted_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS share_grants(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),grantee_user_id TEXT NOT NULL REFERENCES users(id),scope_json TEXT NOT NULL,expires_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS share_lookup ON share_grants(tenant_id,grantee_user_id,owner_user_id,revoked_at);
CREATE TABLE IF NOT EXISTS telemetry_readings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),device_id TEXT NOT NULL REFERENCES devices(id),gateway_id TEXT NOT NULL REFERENCES gateways(id),source_id TEXT NOT NULL,reading_id TEXT NOT NULL,kind TEXT NOT NULL,observed_at TEXT NOT NULL,received_at TEXT NOT NULL,value_num REAL,value_json TEXT,unit TEXT NOT NULL,quality TEXT NOT NULL,firmware TEXT, UNIQUE(tenant_id,source_id,reading_id));
CREATE INDEX IF NOT EXISTS telemetry_lookup ON telemetry_readings(tenant_id,device_id,kind,observed_at DESC);
CREATE TABLE IF NOT EXISTS telemetry_aggregates(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),device_id TEXT NOT NULL REFERENCES devices(id),kind TEXT NOT NULL,bucket_start TEXT NOT NULL,bucket_size_s INTEGER NOT NULL,quality TEXT NOT NULL,count INTEGER NOT NULL,value_min REAL,value_max REAL,value_avg REAL,value_sum REAL,updated_at TEXT NOT NULL,UNIQUE(tenant_id,device_id,kind,bucket_start,bucket_size_s));
CREATE INDEX IF NOT EXISTS telemetry_aggregate_lookup ON telemetry_aggregates(tenant_id,device_id,kind,bucket_start DESC);
CREATE TABLE IF NOT EXISTS sleep_intervals(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),device_id TEXT NOT NULL REFERENCES devices(id),start_at TEXT NOT NULL,end_at TEXT NOT NULL,stage TEXT NOT NULL,quality TEXT NOT NULL,source_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_sessions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),device_id TEXT NOT NULL REFERENCES devices(id),owner_user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT,details_json TEXT NOT NULL DEFAULT '{}',quality TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),device_id TEXT REFERENCES devices(id),kind TEXT NOT NULL,severity TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,created_at TEXT NOT NULL,ack_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),recipient_user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,channel TEXT NOT NULL,status TEXT NOT NULL,payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,sent_at TEXT,read_at TEXT,UNIQUE(recipient_user_id,kind,created_at));
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(tenant_id,recipient_user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS checkins(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,status TEXT NOT NULL,requested_at TEXT NOT NULL,responded_at TEXT,details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS automations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,ast_json TEXT NOT NULL,cooldown_ms INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS automation_runs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),automation_id TEXT NOT NULL REFERENCES automations(id),source_event_id TEXT NOT NULL,rule_version INTEGER NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,error_code TEXT,details_json TEXT NOT NULL DEFAULT '{}',UNIQUE(automation_id,source_event_id,rule_version));
CREATE TABLE IF NOT EXISTS equipment(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT REFERENCES users(id),gateway_id TEXT REFERENCES gateways(id),kind TEXT NOT NULL,display_name TEXT NOT NULL,safety_class TEXT NOT NULL CHECK(safety_class IN('safe_demo','low_risk','safety_critical')),capabilities_json TEXT NOT NULL,watchdog_ms INTEGER NOT NULL,max_rate_hz INTEGER NOT NULL DEFAULT 10,last_seen_at TEXT,status TEXT NOT NULL DEFAULT 'offline',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS control_sessions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),device_id TEXT REFERENCES devices(id),equipment_id TEXT NOT NULL REFERENCES equipment(id),state TEXT NOT NULL CHECK(state IN('DISARMED','ARM_REQUESTED','ARMED','EXPIRED','FAULT')),policy_version TEXT NOT NULL,armed_at TEXT,expires_at TEXT NOT NULL,last_heartbeat_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ctrl_state ON control_sessions(tenant_id,equipment_id,state,expires_at);
CREATE TABLE IF NOT EXISTS control_commands(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),session_id TEXT NOT NULL REFERENCES control_sessions(id),equipment_id TEXT NOT NULL REFERENCES equipment(id),seq INTEGER NOT NULL,action TEXT NOT NULL,payload_json TEXT NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL,acked_at TEXT,executed_at TEXT,idempotency_key TEXT NOT NULL,UNIQUE(tenant_id,equipment_id,idempotency_key),UNIQUE(session_id,seq));
CREATE TABLE IF NOT EXISTS gesture_training_sets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),device_id TEXT REFERENCES devices(id),r2_key TEXT NOT NULL,consent_id TEXT NOT NULL REFERENCES consents(id),dataset_hash TEXT NOT NULL,sample_count INTEGER NOT NULL,created_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS gesture_models(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),model_version TEXT NOT NULL,algorithm TEXT NOT NULL,training_set_id TEXT REFERENCES gesture_training_sets(id),artifact_key TEXT,metrics_json TEXT NOT NULL DEFAULT '{}',state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gesture_mappings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),gesture_key TEXT NOT NULL,equipment_id TEXT NOT NULL REFERENCES equipment(id),action TEXT NOT NULL,args_json TEXT NOT NULL DEFAULT '{}',min_confidence REAL NOT NULL DEFAULT 0.95,requires_approval INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS integrations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),kind TEXT NOT NULL,label TEXT NOT NULL,config_encrypted TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'disabled',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhooks(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),integration_id TEXT REFERENCES integrations(id),url TEXT NOT NULL,secret_ref TEXT NOT NULL,event_types_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_keys(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT REFERENCES users(id),key_prefix TEXT NOT NULL,key_hash TEXT NOT NULL UNIQUE,scopes_json TEXT NOT NULL,expires_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exports(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,state TEXT NOT NULL,r2_key TEXT,expires_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_insights(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),device_id TEXT REFERENCES devices(id),kind TEXT NOT NULL,model_version TEXT NOT NULL,input_window_json TEXT NOT NULL,quality TEXT NOT NULL,explanation TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_feedback(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),owner_user_id TEXT NOT NULL REFERENCES users(id),insight_id TEXT NOT NULL REFERENCES ai_insights(id),feedback TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS billing_subscriptions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),plan_id TEXT NOT NULL,provider TEXT,provider_subscription_ref TEXT,status TEXT NOT NULL,period_end TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS billing_usage(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),metric TEXT NOT NULL,bucket_start TEXT NOT NULL,value_num REAL NOT NULL,updated_at TEXT NOT NULL,UNIQUE(tenant_id,metric,bucket_start));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,tenant_id TEXT,actor_ref TEXT,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,correlation_id TEXT,reason_code TEXT,metadata_safe_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_lookup ON audit_events(tenant_id,created_at DESC,action);
CREATE TABLE IF NOT EXISTS idempotency_keys(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),scope TEXT NOT NULL,idem_key TEXT NOT NULL,response_hash TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,UNIQUE(tenant_id,scope,idem_key));
